from concurrent.futures import Future, ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is odd,
    raises Bad for the odd element with the lowest index in xs.
    """
    with ThreadPoolExecutor() as pool:
        futures: list[Future[int]] = [pool.submit(check, x) for x in xs]
        return [f.result() for f in futures]


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 0]) == [2, 4, 0]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_raises_single_bad() -> None:
    with pytest.raises(Bad) as exc:
        all_even([2, 3, 4])
    assert exc.value.n == 3


def test_all_even_raises_lowest_index_bad() -> None:
    with pytest.raises(Bad) as exc:
        all_even([2, 7, 4, 5, 6])
    assert exc.value.n == 7


def test_all_even_first_element_bad() -> None:
    with pytest.raises(Bad) as exc:
        all_even([1, 2, 4])
    assert exc.value.n == 1
